-- WABYS vocational curricula (generated by scripts/build-curricula.py from
-- db/curricula/wabys-2026.json; edit the JSON and run the script, do not edit by hand).
--
-- Source: WABYS Manual for Vocational Education & Applied Technology Curriculums — Master Curriculum Framework, First Edition 2026
--
-- Eight programmes, each a trade. ELI, AUT and CNC are the electrical,
-- automotive and CNC trades the LMS already had; RMG, EIM, PRT, AIT and CWS
-- are new. Every programme gets a framework WABYS-<code>-2026 whose skills
-- tree is: year × domain (Knowledge / Skills / Attitudes) → module, competency
-- or attitude → content topic, performance criterion or observable behaviour.
-- Each competency also records its domain, year, target performance level
-- (L1–L4), WABYS core attitude (A1–A7) and its full text in both languages.
SET search_path = vtc, public;

-- -----------------------------------------------------------------------------
-- Programme profile and the manual's own code on each trade
-- -----------------------------------------------------------------------------
ALTER TABLE trades
  ADD COLUMN program_code text UNIQUE,     -- the curriculum manual's code ('ELI'); trades.code stays the code used in labs
  ADD COLUMN accent       text,            -- colour that marks the programme's screens
  ADD COLUMN profile      jsonb;           -- bilingual programme card: overview, EQF level, hours, occupations, standards, equipment, tracks, capstone

-- -----------------------------------------------------------------------------
-- Knowledge / skills / attitudes on each competency
-- -----------------------------------------------------------------------------
ALTER TABLE competencies
  ADD COLUMN description_ar text,
  ADD COLUMN ksa            text CHECK (ksa IN ('K', 'S', 'A')),
  ADD COLUMN year           smallint CHECK (year BETWEEN 1 AND 6),
  ADD COLUMN target_level   text,          -- performance level at year end: 'L3', 'L2–L3'
  ADD COLUMN core_attitude  text,          -- WABYS core attitude A1–A7 an attitude contextualises
  ADD COLUMN sort_order     integer;
CREATE INDEX idx_competencies_ksa ON competencies(framework_id, year, ksa);

CREATE TABLE core_attitudes (
  code           text PRIMARY KEY CHECK (code ~ '^A[0-9]$'),
  name           text NOT NULL,
  name_ar        text,
  indicators     text,
  indicators_ar  text
);
INSERT INTO core_attitudes (code, name, name_ar, indicators, indicators_ar) VALUES
  ('A1', 'Safety Consciousness', 'الوعي بالسلامة', 'Uses PPE unprompted; stops unsafe work; reports hazards', 'يستخدم معدات الوقاية دون تذكير؛ يوقف العمل غير الآمن؛ يبلغ عن المخاطر'),
  ('A2', 'Responsibility & Reliability', 'المسؤولية والاعتمادية', 'Punctual; completes tasks; owns mistakes', 'ملتزم بالمواعيد؛ يُنجز المهام؛ يعترف بأخطائه'),
  ('A3', 'Quality Orientation', 'التوجه نحو الجودة', 'Self-checks work; meets tolerances; documents results', 'يراجع عمله بنفسه؛ يلتزم بالتفاوتات؛ يوثق النتائج'),
  ('A4', 'Collaboration & Communication', 'التعاون والتواصل', 'Shares information; respects roles; communicates clearly', 'يشارك المعلومات؛ يحترم الأدوار؛ يتواصل بوضوح'),
  ('A5', 'Customer & Service Orientation', 'التوجه نحو العميل والخدمة', 'Understands customer needs; explains work; courteous', 'يفهم احتياجات العميل؛ يشرح عمله؛ لبق'),
  ('A6', 'Environmental & Resource Stewardship', 'الحفاظ على البيئة والموارد', 'Minimizes waste; sorts and disposes correctly; saves energy', 'يقلل الهالك؛ يفرز المخلفات ويتخلص منها بشكل صحيح؛ يوفر الطاقة'),
  ('A7', 'Learning Agility & Ethics', 'سرعة التعلم والأخلاقيات', 'Seeks feedback; adapts to new tech; honest and confidential', 'يطلب الملاحظات؛ يتكيف مع التقنيات الجديدة؛ أمين ويحفظ السرية');

-- -----------------------------------------------------------------------------
-- The programmes
-- -----------------------------------------------------------------------------
UPDATE trades SET name = 'Electrical Installations', name_ar = 'التركيبات الكهربائية', program_code = 'ELI', accent = '#e8a70a',
  profile = '{"occupation": {"en": "Electrical Installation Technician", "ar": "فني تركيبات كهربائية"}, "overview": {"en": "Prepares Electrical Installation Technicians to plan, install, test, commission and maintain low-voltage electrical systems in residential, commercial and light-industrial buildings, including motor control, building automation and renewable-energy integration. Benchmarked to the German occupation Elektroniker/-in für Energie- und Gebäudetechnik and IEC 60364 practice.", "ar": "يُعدّ البرنامج فنيي التركيبات الكهربائية لتخطيط وتركيب واختبار وتشغيل وصيانة أنظمة الجهد المنخفض في المباني السكنية والتجارية والصناعية الخفيفة، بما في ذلك التحكم في المحركات وأتمتة المباني وتكامل الطاقة المتجددة. مرجعيته المهنة الألمانية Elektroniker/-in für Energie- und Gebäudetechnik وممارسات IEC 60364."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Building electrician, panel builder, maintenance electrician, PV installer, smart-home technician", "ar": "كهربائي مبانٍ، فني تجميع لوحات، كهربائي صيانة، فني تركيب طاقة شمسية، فني منازل ذكية"}, "standards": "IEC 60364, IEC 61439, IEC 60204-1, IEC 62446, NFPA 70E", "equipment": {"en": "Installation booths, motor-control trainers, PLC trainers (Siemens S7-1200), KNX kits, PV training rig, multifunction installation tester", "ar": "كبائن تركيبات، وحدات تدريب التحكم في المحركات، وحدات تدريب PLC ‏(Siemens S7-1200)، أطقم KNX، جهاز تدريب الطاقة الشمسية، جهاز اختبار التركيبات متعدد الوظائف"}, "tracks": [{"en": "Industrial Automation", "ar": "الأتمتة الصناعية"}, {"en": "Smart Buildings", "ar": "المباني الذكية"}, {"en": "Renewable Energy Systems", "ar": "أنظمة الطاقة المتجددة"}], "capstone": {"en": "Design, install and commission a complete electrical system for a small commercial unit: distribution, lighting, power and one automated function (PLC, KNX or PV), drawings and cable calculations, full initial verification, customer handover and a 30-minute technical interview. 80 hours, 40% of the final examination.", "ar": "تصميم وتركيب وتشغيل نظام كهربائي متكامل لوحدة تجارية صغيرة: التوزيع والإنارة والقوى ووظيفة مؤتمتة واحدة (PLC أو KNX أو طاقة شمسية)، والمخططات وحسابات الكابلات، والتحقق الأولي الكامل، والتسليم للعميل، ومقابلة فنية مدتها 30 دقيقة. 80 ساعة، 40% من الامتحان النهائي."}, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums — Master Curriculum Framework, First Edition 2026", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي — الإطار المرجعي الرئيسي للمناهج، الطبعة الأولى 2026"}}'::jsonb
 WHERE id = 'elec';
UPDATE trades SET name = 'Automotive Maintenance & Repair', name_ar = 'صيانة وإصلاح السيارات', program_code = 'AUT', accent = '#d9463b',
  profile = '{"occupation": {"en": "Automotive Mechatronics Technician", "ar": "فني ميكاترونكس سيارات"}, "overview": {"en": "Prepares Automotive Mechatronics Technicians to service, diagnose and repair passenger cars and light commercial vehicles, covering mechanical, electrical/electronic and hybrid and battery-electric systems. Diagnostic competence and high-voltage safety are central. Benchmarked to the German occupation Kfz-Mechatroniker/-in and OEM dealer training.", "ar": "يُعدّ البرنامج فنيي ميكاترونكس السيارات لخدمة وتشخيص وإصلاح سيارات الركوب والمركبات التجارية الخفيفة، ويغطي الأنظمة الميكانيكية والكهربائية والإلكترونية والهجينة والكهربائية بالبطاريات. الكفاءة في التشخيص وسلامة الجهد العالي محوريتان. مرجعيته المهنة الألمانية Kfz-Mechatroniker/-in وتدريب وكلاء المصنّعين."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Service technician, diagnostic technician, EV/hybrid technician, service advisor (with experience)", "ar": "فني خدمة، فني تشخيص، فني سيارات كهربائية وهجينة، مستشار خدمة (مع الخبرة)"}, "standards": "OEM service procedures, SAE J1979 (OBD-II), ISO 15765 (CAN), ECE R100, DGUV 209-093", "equipment": {"en": "Two-post lifts, engine cutaway and running stands, OEM-level scan tools, oscilloscopes, wheel aligner, A/C recovery station, HV-insulated tool kits, EV training vehicle", "ar": "روافع بعمودين، محركات مقطعية وعلى حوامل تشغيل، أجهزة فحص بمستوى المصنّع، أوسيلوسكوبات، جهاز ضبط زوايا العجلات، محطة استرجاع غاز التكييف، أطقم عدد معزولة للجهد العالي، سيارة كهربائية للتدريب"}, "tracks": [{"en": "Electric & Hybrid Vehicles", "ar": "السيارات الكهربائية والهجينة"}, {"en": "Advanced Diagnostics & ADAS", "ar": "التشخيص المتقدم وأنظمة مساعدة السائق"}, {"en": "Commercial Vehicle Systems", "ar": "أنظمة المركبات التجارية"}], "capstone": {"en": "Complete diagnostic case study on a customer vehicle with at least one electronic/network fault and one mechanical fault (one HV fault for the EV track): customer interview, diagnostic plan, evidenced tests, repair and verification, repair report and estimate, panel presentation. 60 hours, 40% of the final examination.", "ar": "دراسة حالة تشخيصية كاملة على سيارة عميل بها عطل إلكتروني أو شبكي وعطل ميكانيكي على الأقل (وعطل جهد عالٍ لمسار السيارات الكهربائية): مقابلة العميل، خطة التشخيص، اختبارات موثقة، الإصلاح والتحقق، تقرير الإصلاح والتقدير، والعرض أمام اللجنة. 60 ساعة، 40% من الامتحان النهائي."}, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums — Master Curriculum Framework, First Edition 2026", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي — الإطار المرجعي الرئيسي للمناهج، الطبعة الأولى 2026"}}'::jsonb
 WHERE id = 'auto';
UPDATE trades SET name = 'CNC Machining & Turning', name_ar = 'الخراطة والتشغيل الرقمي CNC', program_code = 'CNC', accent = '#2f8fd8',
  profile = '{"occupation": {"en": "Cutting Machine Operator & CNC Machinist", "ar": "مشغل ماكينات قطع وفني تشغيل CNC"}, "overview": {"en": "Prepares Cutting Machine Operators and CNC Machinists to produce precision components from metals and engineering plastics on conventional lathes and mills and CNC turning and machining centres: reading drawings, planning sequences, writing and optimising CNC programs, setting up machines and verifying quality. Benchmarked to the German occupation Zerspanungsmechaniker/-in and ISO GPS.", "ar": "يُعدّ البرنامج مشغلي ماكينات القطع وفنيي CNC لإنتاج مكونات دقيقة من المعادن واللدائن الهندسية على المخارط والفرايز التقليدية ومراكز الخراطة والتشغيل CNC: قراءة الرسومات، وتخطيط التسلسل، وكتابة برامج CNC وتحسينها، وإعداد الماكينات، والتحقق من الجودة. مرجعيته المهنة الألمانية Zerspanungsmechaniker/-in ومواصفات ISO للمنتجات الهندسية."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "CNC operator, CNC setter-programmer, conventional turner/miller, quality inspector, CAM programmer (junior)", "ar": "مشغل CNC، فني إعداد وبرمجة CNC، خراط وفرّاز تقليدي، مفتش جودة، مبرمج CAM (مبتدئ)"}, "standards": "ISO 128 / ISO 129, ISO 286, ISO 1101, ISO 1302 / 21920, ISO 6983, ISO 12100", "equipment": {"en": "Conventional lathes and milling machines, CNC lathe (Fanuc/Siemens control), 3-axis vertical machining centre, CAD/CAM software, CNC simulators, metrology lab with CMM", "ar": "مخارط وفرايز تقليدية، مخرطة CNC ‏(تحكم Fanuc/Siemens)، مركز تشغيل رأسي ثلاثي المحاور، برامج CAD/CAM، محاكيات CNC، معمل قياس بماكينة CMM"}, "tracks": [{"en": "CAM Programming & 5-Axis", "ar": "برمجة CAM والتشغيل خماسي المحاور"}, {"en": "Precision Turning & Mill-Turn", "ar": "الخراطة الدقيقة والخراطة-التفريز"}, {"en": "Tool & Mold Making", "ar": "صناعة العدد والقوالب"}], "capstone": {"en": "Manufacture a functional multi-part assembly (e.g. a precision vise or gear pump housing) with turned, milled and threaded features and at least one H7/g6 fit: process plans, CAM and manual programs, setup and machining, FAI report, assembly and a cost and cycle-time analysis. 80 hours, 40% of the final examination.", "ar": "تصنيع مجموعة وظيفية متعددة الأجزاء (مثل منجلة دقيقة أو جسم مضخة تروس) بها أجزاء مخروطة ومفرزة ومقلوظة وازدواج H7/g6 واحد على الأقل: خطط العمليات، برامج CAM ويدوية، الإعداد والتشغيل، تقرير فحص القطعة الأولى، التجميع، وتحليل التكلفة وزمن الدورة. 80 ساعة، 40% من الامتحان النهائي."}, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums — Master Curriculum Framework, First Edition 2026", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي — الإطار المرجعي الرئيسي للمناهج، الطبعة الأولى 2026"}}'::jsonb
 WHERE id = 'cnc';
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('rmg', 'RMG', 'Ready-Made Garments & Fashion Production', 'الملابس الجاهزة وإنتاج الأزياء', 'M8 3 3 6l2 4 2-1v12h10V9l2 1 2-4-5-3a4 4 0 0 1-8 0z', 50, 'RMG', '#c2417a',
  '{"occupation": {"en": "Garment Production Technician", "ar": "فني إنتاج ملابس"}, "overview": {"en": "Prepares Garment Production Technicians to turn design concepts into high-quality, cost-efficient garments at industrial scale: textile science, pattern making and grading, cutting room, sewing technology, finishing, quality assurance and production engineering, up to 2D/3D CAD, automated cutting and digital printing. Benchmarked to the German occupations Modenäher/-in and Maßschneider/-in and international buyer expectations.", "ar": "يُعدّ البرنامج فنيي إنتاج الملابس لتحويل أفكار التصميم إلى ملابس عالية الجودة وفعالة التكلفة على نطاق صناعي: علوم النسيج، وعمل الباترون وتدريجه، وصالة القص، وتكنولوجيا الخياطة، والتشطيب، وضمان الجودة، والهندسة الإنتاجية، وصولًا إلى CAD ثنائي وثلاثي الأبعاد والقص الآلي والطباعة الرقمية. مرجعيته المهنتان الألمانيتان Modenäher/-in وMaßschneider/-in وتوقعات المشترين الدوليين."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Sample maker, pattern maker/grader, cutting master, line supervisor, QC inspector, industrial engineering assistant", "ar": "صانع عينات، صانع ومدرّج باترونات، رئيس قص، مشرف خط، مفتش جودة، مساعد هندسة صناعية"}, "standards": "ISO 3635 / 8559, ISO 4915 / 4916, AQL ISO 2859-1, OEKO-TEX, WRAP, amfori BSCI, Higg Index", "equipment": {"en": "Lockstitch, overlock, coverstitch, bartack, buttonhole and button-sew machines; spreading tables; straight-knife and band-knife cutters; fusing press; steam finishing; CAD pattern system; 3D virtual fitting software", "ar": "ماكينات الغرزة المقفولة والأوفرلوك والكافر ستيتش والبارتاك والعراوي وتركيب الأزرار؛ طاولات الفرد؛ مقصات السكين المستقيمة والشريطية؛ مكبس اللصق الحراري؛ التشطيب بالبخار؛ نظام CAD للباترون؛ برامج القياس الافتراضي ثلاثي الأبعاد"}, "tracks": [{"en": "Pattern Engineering & 3D CAD", "ar": "هندسة الباترون وCAD ثلاثي الأبعاد"}, {"en": "Production & Industrial Engineering", "ar": "الإنتاج والهندسة الصناعية"}, {"en": "Quality & Compliance Management", "ar": "إدارة الجودة والامتثال"}], "capstone": {"en": "From tech pack to production-ready style: patterns (manual and CAD), a 3D virtual and a physical fit sample, marker and consumption, operation bulletin with SMVs and a balanced line, garment costing, a 12-piece mini-run across 3 sizes inspected to AQL 2.5 and a sustainability and compliance statement. 90 hours, 40% of the final examination.", "ar": "من ملف المواصفات إلى موديل جاهز للإنتاج: الباترونات (يدويًا وCAD)، عينة افتراضية ثلاثية الأبعاد وعينة قياس فعلية، الماركر والاستهلاك، نشرة العمليات بالدقائق القياسية وخط متوازن، تكلفة القطعة، تشغيلة مصغرة من 12 قطعة بثلاثة مقاسات تُفحص وفق AQL 2.5، وبيان الاستدامة والامتثال. 90 ساعة، 40% من الامتحان النهائي."}, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums — Master Curriculum Framework, First Edition 2026", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي — الإطار المرجعي الرئيسي للمناهج، الطبعة الأولى 2026"}}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('eim', 'EIM', 'Equipment Installation & Maintenance', 'تركيب وصيانة المعدات', 'M14.7 6.3a4 4 0 0 0-5.4 5.4L3 18l3 3 6.3-6.3a4 4 0 0 0 5.4-5.4l-2.5 2.5-2.5-.6-.6-2.5z', 60, 'EIM', '#3a9d5d',
  '{"occupation": {"en": "Industrial Mechatronics & Maintenance Technician", "ar": "فني ميكاترونكس وصيانة صناعية"}, "overview": {"en": "Prepares Industrial Mechatronics & Maintenance Technicians to install, align, commission, maintain and repair production equipment combining mechanical, hydraulic, pneumatic, electrical and control elements, with emphasis on rigging, precision alignment, fluid power, condition monitoring and reliability-centred maintenance. Benchmarked to the German occupations Industriemechaniker/-in and Mechatroniker/-in.", "ar": "يُعدّ البرنامج فنيي الميكاترونكس والصيانة الصناعية لتركيب ومحاذاة وتشغيل وصيانة وإصلاح معدات الإنتاج التي تجمع العناصر الميكانيكية والهيدروليكية والهوائية والكهربائية وعناصر التحكم، مع التركيز على الرفع والتركيب والمحاذاة الدقيقة وقدرة الموائع ومراقبة الحالة والصيانة المرتكزة على الاعتمادية. مرجعيته المهنتان الألمانيتان Industriemechaniker/-in وMechatroniker/-in."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Maintenance mechanic, mechatronics technician, installation/commissioning technician, condition-monitoring technician, maintenance planner (junior)", "ar": "ميكانيكي صيانة، فني ميكاترونكس، فني تركيب وتشغيل، فني مراقبة حالة، مخطط صيانة (مبتدئ)"}, "standards": "ISO 12100, ISO 4413, ISO 4414, ISO 1219, ISO 10816 / 20816, ISO 55000, EN 13306, LOLER", "equipment": {"en": "Pump and gearbox rigs, laser shaft-alignment system, hydraulic and electro-pneumatic trainers, mechatronic production line (MPS-type), vibration analyser, thermal camera", "ar": "منصات تدريب المضخات وعلب التروس، نظام محاذاة الأعمدة بالليزر، وحدات تدريب هيدروليكية وكهروهوائية، خط إنتاج ميكاتروني (من نوع MPS)، محلل اهتزازات، كاميرا حرارية"}, "tracks": [{"en": "Predictive Maintenance & Reliability", "ar": "الصيانة التنبؤية والاعتمادية"}, {"en": "Mechatronics & Automated Lines", "ar": "الميكاترونكس والخطوط الآلية"}, {"en": "Equipment Installation & Commissioning", "ar": "تركيب المعدات وتشغيلها"}], "capstone": {"en": "Reliability improvement of a critical production asset in the host enterprise: CMMS history and MTBF/MTTR, condition monitoring (vibration, thermography, oil), FMEA and RCA, a corrective intervention under LOTO and permits, recommissioning, an improved PM/PdM plan and a cost-benefit presentation. 80 hours, 40% of the final examination.", "ar": "تحسين اعتمادية أصل إنتاجي حرج في المنشأة المضيفة: تحليل سجل CMMS وحساب MTBF/MTTR، مراقبة الحالة (اهتزاز، تصوير حراري، زيت)، تحليل FMEA والسبب الجذري، تدخل تصحيحي مع الإقفال والتصاريح، إعادة التشغيل، خطة صيانة وقائية وتنبؤية محسّنة، وعرض التكلفة والعائد. 80 ساعة، 40% من الامتحان النهائي."}, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums — Master Curriculum Framework, First Edition 2026", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي — الإطار المرجعي الرئيسي للمناهج، الطبعة الأولى 2026"}}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('prt', 'PRT', 'Printing Technologies', 'تكنولوجيا الطباعة', 'M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 14h12v7H6z', 70, 'PRT', '#7a4fd1',
  '{"occupation": {"en": "Print Media Technologist", "ar": "فني تكنولوجيا الطباعة والوسائط"}, "overview": {"en": "Prepares Print Media Technologists to manage the complete print production chain: prepress and colour management, offset lithography, flexography and packaging, digital and wide-format, screen printing and post-press finishing. Modern print is data-driven: colour measurement, workflow automation and sustainable substrates and inks. Benchmarked to the German occupation Medientechnologe/-in Druck and ISO 12647.", "ar": "يُعدّ البرنامج فنيي تكنولوجيا الطباعة لإدارة سلسلة الإنتاج الطباعي كاملة: ما قبل الطباعة وإدارة الألوان، والأوفست، والفلكسوجراف والتغليف، والطباعة الرقمية وعريضة النسق، والشاشة الحريرية، وتشطيب ما بعد الطباعة. الطباعة الحديثة قائمة على البيانات: قياس اللون وأتمتة سير العمل والخامات والأحبار المستدامة. مرجعيته المهنة الألمانية Medientechnologe/-in Druck ومعايير ISO 12647."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Prepress operator, offset press operator, flexo printer, digital print technician, finishing operator, colour/quality technician, print production planner", "ar": "مشغل ما قبل الطباعة، مشغل ماكينة أوفست، طابع فلكسو، فني طباعة رقمية، مشغل تشطيب، فني لون وجودة، مخطط إنتاج طباعي"}, "standards": "ISO 12647-2 / -6 / -8, ISO 15930 (PDF/X), ISO 13655, G7, Fogra, EU 1935/2004, FSC", "equipment": {"en": "Sheetfed offset press, flexo label press, CTP platesetter, digital and wide-format printers, screen-printing station, guillotine and folder, spectrophotometer", "ar": "ماكينة أوفست بالأفرخ، ماكينة فلكسو للملصقات، جهاز تجهيز الألواح CTP، طابعات رقمية وعريضة النسق، محطة شاشة حريرية، مقصلة وماكينة طي، جهاز قياس الطيف اللوني"}, "tracks": [{"en": "Packaging & Flexo Printing", "ar": "التغليف وطباعة الفلكسو"}, {"en": "Digital & Wide-Format Production", "ar": "الإنتاج الرقمي وعريض النسق"}, {"en": "Prepress & Colour Management", "ar": "ما قبل الطباعة وإدارة الألوان"}], "capstone": {"en": "End-to-end production of a branded packaging and print campaign: a folding carton or label with dieline, barcode and brand spot colour; a bilingual (Arabic/English) brochure; and a variable-data or wide-format piece, with preflight reports, contract proofs, ISO 12647 QC data, a cost estimate and a sustainability statement. 80 hours, 40% of the final examination.", "ar": "إنتاج متكامل لحملة تغليف وطباعة لعلامة تجارية: علبة كرتونية أو ملصق بخط قالب وباركود ولون خاص للعلامة؛ وكتيب ثنائي اللغة (عربي/إنجليزي)؛ وقطعة بيانات متغيرة أو عريضة النسق، مع تقارير الفحص المسبق والبروفات التعاقدية وبيانات الجودة وفق ISO 12647 وتقدير التكلفة وبيان الاستدامة. 80 ساعة، 40% من الامتحان النهائي."}, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums — Master Curriculum Framework, First Edition 2026", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي — الإطار المرجعي الرئيسي للمناهج، الطبعة الأولى 2026"}}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('ait', 'AIT', 'Artificial Intelligence for Technicians', 'الذكاء الاصطناعي للفنيين', 'M8 8h8v8H8zM5 5h14v14H5zM9 2v3M15 2v3M9 19v3M15 19v3M2 9h3M2 15h3M19 9h3M19 15h3', 80, 'AIT', '#0f9fb0',
  '{"occupation": {"en": "Applied AI & Data Technician", "ar": "فني ذكاء اصطناعي وبيانات تطبيقي"}, "overview": {"en": "Prepares Applied AI & Data Technicians who bridge the shop floor and the data layer: collecting and preparing industrial data, deploying sensors and edge devices, integrating ready-made AI tools (vision inspection, predictive maintenance, generative AI assistants), monitoring models and applying AI responsibly and safely. Aligned with Fachinformatiker/-in für Daten- und Prozessanalyse and the OECD, UNESCO and ISO/IEC 42001 frameworks.", "ar": "يُعدّ البرنامج فنيي الذكاء الاصطناعي والبيانات التطبيقيين الذين يربطون أرض المصنع بطبقة البيانات: جمع البيانات الصناعية وتجهيزها، ونشر الحساسات وأجهزة الحافة، ودمج أدوات الذكاء الاصطناعي الجاهزة (الفحص بالرؤية، الصيانة التنبؤية، المساعدات التوليدية)، ومراقبة النماذج، وتطبيق الذكاء الاصطناعي بمسؤولية وأمان. يتوافق مع مهنة Fachinformatiker/-in für Daten- und Prozessanalyse وأطر OECD وUNESCO وISO/IEC 42001."}, "eqf": "EQF 4–5", "hours": 4800, "occupations": {"en": "AI/data technician, industrial IoT technician, vision-inspection technician, AI tools integrator, data annotation lead, MLOps support technician, AI-enabled maintenance technician", "ar": "فني ذكاء اصطناعي وبيانات، فني إنترنت أشياء صناعي، فني فحص بالرؤية، مُدمج أدوات ذكاء اصطناعي، قائد وسم بيانات، فني دعم MLOps، فني صيانة مدعوم بالذكاء الاصطناعي"}, "standards": "ISO/IEC 22989, ISO/IEC 42001, ISO/IEC 23894, ISO/IEC 27001, IEC 62443, OECD & UNESCO AI principles", "equipment": {"en": "GPU-enabled lab workstations, Python/Jupyter environment, edge AI kits, industrial cameras and lighting, IoT sensor kits, PLC with OPC UA, cloud sandbox accounts", "ar": "محطات عمل بمعالجات رسوميات، بيئة Python/Jupyter، أطقم ذكاء اصطناعي طرفية، كاميرات وإضاءة صناعية، أطقم حساسات إنترنت الأشياء، PLC مع OPC UA، حسابات سحابية تجريبية"}, "tracks": [{"en": "AI for Smart Manufacturing & Maintenance", "ar": "الذكاء الاصطناعي للتصنيع والصيانة الذكية"}, {"en": "Computer Vision & Quality Inspection", "ar": "الرؤية الحاسوبية وفحص الجودة"}, {"en": "Generative AI & Workflow Automation for Enterprises", "ar": "الذكاء الاصطناعي التوليدي وأتمتة سير العمل للمنشآت"}], "capstone": {"en": "Deploy a responsible AI solution for a real vocational problem (e.g. vision inspection of CNC parts or predictive maintenance of an EIM asset): problem and metrics, documented data, a deployed solution, an AI risk and impact assessment and model card, two weeks in production with monitoring, user training and a value presentation. 100 hours, 40% of the final examination.", "ar": "نشر حل ذكاء اصطناعي مسؤول لمشكلة مهنية حقيقية (مثل الفحص بالرؤية لقطع CNC أو الصيانة التنبؤية لأصل في برنامج الصيانة): تحديد المشكلة والمقاييس، بيانات موثقة، حل منشور، تقييم مخاطر وأثر وبطاقة نموذج، أسبوعان في التشغيل الفعلي مع المراقبة، تدريب المستخدمين، وعرض القيمة المحققة. 100 ساعة، 40% من الامتحان النهائي."}, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums — Master Curriculum Framework, First Edition 2026", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي — الإطار المرجعي الرئيسي للمناهج، الطبعة الأولى 2026"}}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('cws', 'CWS', '21st Century Work Skills', 'مهارات العمل للقرن الحادي والعشرين', 'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM2 21v-1a7 7 0 0 1 14 0v1M16 3.1a4 4 0 0 1 0 7.8M22 21v-1a7 7 0 0 0-4-6.3', 90, 'CWS', '#8a6d3b',
  '{"occupation": {"en": "Workplace Coordination & Business Support Technician", "ar": "فني تنسيق العمل ودعم الأعمال"}, "overview": {"en": "The transversal spine of every WABYS specialisation: communication, problem solving, teamwork, self-management, digital fluency and professional conduct, in a structured, assessed three-year progression. Integrated mode (mandatory): 120 institute hours a year inside every technical programme plus workplace evidence in the logbook. Standalone mode (optional): a full three-year programme for roles such as production coordinator, technical customer service, team leader and training assistant.", "ar": "العمود الفقري المشترك لكل تخصصات وابيز: التواصل، وحل المشكلات، والعمل الجماعي، وإدارة الذات، والطلاقة الرقمية، والسلوك المهني، في تدرج منظم ومُقيَّم على ثلاث سنوات. النمط المدمج (إلزامي): 120 ساعة سنويًا داخل كل برنامج فني مع أدلة تطبيق في سجل التدريب. النمط المستقل (اختياري): برنامج كامل لثلاث سنوات لأدوار مثل منسق الإنتاج وخدمة العملاء الفنية وقائد الفريق ومساعد التدريب."}, "eqf": "EQF 4", "hours": 360, "occupations": {"en": "Employability, team leadership readiness, entrepreneurial capability, lifelong learning", "ar": "قابلية التوظيف، الجاهزية لقيادة الفريق، القدرة الريادية، التعلم مدى الحياة"}, "standards": "OECD Learning Compass 2030, WEF Future of Jobs, EU DigComp 2.2, EntreComp, Handlungskompetenz", "equipment": {"en": "Training rooms, digital productivity tools, logbook, team project boards", "ar": "قاعات تدريب، أدوات إنتاجية رقمية، سجل التدريب، لوحات المشروعات الجماعية"}, "tracks": [], "capstone": {"en": "Professional leadership portfolio and improvement pitch, integrated with the learner''s technical capstone: documented leadership evidence, a bilingual professional portfolio, a 10-minute data-backed improvement pitch to an industry panel and a structured mock interview. 20% of the host programme''s final examination.", "ar": "ملف القيادة المهنية وعرض التحسين، مدمج مع مشروع التخرج الفني للمتدرب: أدلة موثقة على القيادة، ملف أعمال مهني ثنائي اللغة، عرض تحسين مدعوم بالبيانات مدته 10 دقائق أمام لجنة من الصناعة، ومقابلة تجريبية منظمة. 20% من الامتحان النهائي للبرنامج المضيف."}, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums — Master Curriculum Framework, First Edition 2026", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي — الإطار المرجعي الرئيسي للمناهج، الطبعة الأولى 2026"}}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
