-- Elements: knowledge modules, skill competencies and attitudes
INSERT INTO competencies (framework_id, parent_id, code, title, title_ar, description, description_ar, kind, ksa, year, nominal_hours,
                          target_level, core_attitude, is_safety_critical, sort_order)
SELECT f.id, p.id, v.code, v.title, v.title_ar, v.descr, v.descr_ar, 'element', v.ksa, v.year, v.hours, v.lvl, v.core, v.safety, v.sort
  FROM (VALUES
  ('WABYS-ELI-2026', 'ELI-Y1-K-01', 'ELI-Y1-K', 'Electrical Safety & the Five Safety Rules', 'السلامة الكهربائية والقواعد الخمس للسلامة', 'Effects of current on the human body; the five safety rules (disconnect, secure against reconnection, verify absence of voltage, earth and short-circuit, cover adjacent live parts); lockout/tagout; first aid for electric shock; fire classes', 'تأثيرات التيار على جسم الإنسان؛ قواعد السلامة الخمس (الفصل، التأمين ضد إعادة التوصيل، التحقق من انعدام الجهد، التأريض وقصر الدائرة، تغطية الأجزاء المكهربة المجاورة)؛ الإقفال ووضع البطاقات (LOTO)؛ الإسعافات الأولية للصعق الكهربائي؛ فئات الحرائق', 'K', 1, 40, NULL, NULL, false, 1),
  ('WABYS-ELI-2026', 'ELI-Y1-K-02', 'ELI-Y1-K', 'DC Circuit Fundamentals', 'أساسيات دوائر التيار المستمر', 'Charge, voltage, current, resistance; Ohm''s law; power and energy; series, parallel, and mixed circuits; Kirchhoff''s laws; voltage dividers', 'الشحنة والجهد والتيار والمقاومة؛ قانون أوم؛ القدرة والطاقة؛ التوصيل على التوالي والتوازي والمختلط؛ قوانين كيرشوف؛ مقسمات الجهد', 'K', 1, 60, NULL, NULL, false, 2),
  ('WABYS-ELI-2026', 'ELI-Y1-K-03', 'ELI-Y1-K', 'AC Fundamentals', 'أساسيات التيار المتردد', 'Sinusoidal quantities; frequency, RMS, peak; inductance and capacitance; reactance and impedance; phase angle; active, reactive, apparent power; power factor', 'الكميات الجيبية؛ التردد والقيمة الفعالة (RMS) والقيمة العظمى؛ الحث والسعة؛ المفاعلة والمعاوقة؛ زاوية الطور؛ القدرة الفعالة وغير الفعالة والظاهرية؛ معامل القدرة', 'K', 1, 60, NULL, NULL, false, 3),
  ('WABYS-ELI-2026', 'ELI-Y1-K-04', 'ELI-Y1-K', 'Materials, Conductors & Cables', 'المواد والموصلات والكابلات', 'Conductor materials; insulation classes; cable types (NYM, NYY, XLPE, flexible); color codes; current-carrying capacity basics; conduit and trunking systems', 'مواد الموصلات؛ فئات العزل؛ أنواع الكابلات (NYM وNYY وXLPE والمرنة)؛ أكواد الألوان؛ أساسيات سعة حمل التيار؛ أنظمة المواسير والمجاري', 'K', 1, 40, NULL, NULL, false, 4),
  ('WABYS-ELI-2026', 'ELI-Y1-K-05', 'ELI-Y1-K', 'Technical Drawing & Electrical Symbols', 'الرسم الفني والرموز الكهربائية', 'IEC 60617 symbols; installation plans; circuit, wiring, and terminal diagrams; reading architectural floor plans', 'رموز IEC 60617؛ مخططات التركيب؛ مخططات الدوائر والتوصيلات والأطراف؛ قراءة المساقط المعمارية', 'K', 1, 50, NULL, NULL, false, 5),
  ('WABYS-ELI-2026', 'ELI-Y1-K-06', 'ELI-Y1-K', 'Domestic Installation Circuits', 'دوائر التركيبات المنزلية', 'Lighting circuits (one-way, two-way, intermediate, impulse relay); socket circuits; distribution board layout; circuit separation', 'دوائر الإنارة (مفتاح مفرد، مفتاح تحويل، مفتاح وسيط، مرحل نبضي)؛ دوائر المقابس؛ تخطيط لوحة التوزيع؛ فصل الدوائر', 'K', 1, 50, NULL, NULL, false, 6),
  ('WABYS-ELI-2026', 'ELI-Y1-K-07', 'ELI-Y1-K', 'Protective Devices', 'أجهزة الحماية', 'Fuses; MCB characteristics (B, C, D); RCDs (types AC, A, B); selectivity basics; overload vs short-circuit protection', 'المصهرات؛ خصائص القواطع المصغرة MCB ‏(B وC وD)؛ قواطع التيار المتبقي RCD ‏(الأنواع AC وA وB)؛ أساسيات الانتقائية؛ الحماية من الحمل الزائد مقابل قصر الدائرة', 'K', 1, 40, NULL, NULL, false, 7),
  ('WABYS-ELI-2026', 'ELI-Y1-K-08', 'ELI-Y1-K', 'Measurement Principles', 'مبادئ القياس', 'Analog vs digital meters; CAT ratings; measurement of U, I, R; clamp meters; measurement errors and tolerance', 'أجهزة القياس التناظرية مقابل الرقمية؛ تصنيفات CAT؛ قياس الجهد والتيار والمقاومة؛ أجهزة القياس الكلابية؛ أخطاء القياس والتفاوت المسموح', 'K', 1, 30, NULL, NULL, false, 8),
  ('WABYS-ELI-2026', 'ELI-Y1-K-09', 'ELI-Y1-K', 'Technical Mathematics & Physics', 'الرياضيات والفيزياء الفنية', 'Unit conversion; formula transposition; trigonometry for AC; percentages; basic magnetism and electromagnetism', 'تحويل الوحدات؛ إعادة ترتيب المعادلات؛ حساب المثلثات للتيار المتردد؛ النسب المئوية؛ أساسيات المغناطيسية والكهرومغناطيسية', 'K', 1, 60, NULL, NULL, false, 9),
  ('WABYS-ELI-2026', 'ELI-Y1-K-10', 'ELI-Y1-K', 'Technical English for Electricians I', 'اللغة الإنجليزية الفنية للكهربائيين 1', 'Tool and component vocabulary; reading datasheets; safety signs and instructions', 'مفردات العدد والمكونات؛ قراءة صحائف البيانات؛ علامات وتعليمات السلامة', 'K', 1, 50, NULL, NULL, false, 10),
  ('WABYS-ELI-2026', 'ELI-Y1-S-01', 'ELI-Y1-S', 'Apply the five safety rules', 'تطبيق قواعد السلامة الخمس', 'All five rules executed in correct sequence; voltage absence verified with two-pole tester proven before and after; LOTO tag completed', 'تنفيذ القواعد الخمس بالترتيب الصحيح؛ التحقق من انعدام الجهد بجهاز اختبار ثنائي القطب مع إثبات صلاحيته قبل الاختبار وبعده؛ استكمال بطاقة الإقفال LOTO', 'S', 1, NULL, 'L3', NULL, true, 1),
